groups=[]
def g(id,name,color,summary,detail,sources): groups.append(dict(id=id,name=name,color=color,summary=summary,detail=detail,sources=sources))
g('italian','Italianos','#c86645','Una corriente enorme, muchas regiones de origen.','Las pertenencias locales, los oficios y las redes importaban tanto como la nacionalidad. Buenos Aires y la región pampeana concentraron llegadas, pero también hubo inserción en economías como la vitivinicultura cuyana. Las diferencias con quienes emigraron a Estados Unidos permiten estudiar el peso del destino.',['baily','language','cuyo'])
g('spanish','Españoles','#b59b46','Familias y asociaciones a ambos lados del océano.','La migración española del siglo XIX y XX es distinta de la colonización imperial. Galicia, Asturias, el País Vasco, Cataluña y otras regiones tuvieron redes propias. La denominación cotidiana «gallego» no equivale a un origen comprobado. La ayuda familiar podía orientar destino, alojamiento y ocupación.',['moya','galicianwomen'])
g('french','Franceses','#748c69','Una presencia que excede la influencia cultural.','Artesanos, comerciantes y familias rurales integraron una corriente con fuerte componente regional. Tandil y las colonias agrícolas ayudan a mirar fuera de Buenos Aires. La investigación de Otero permite separar una cultura francesa admirada por las élites de las experiencias concretas de inmigrantes.',['otero','subsidy'])
g('swiss','Suizos y colonias','#849b9e','Colonización, lenguas y religiones diversas.','Esperanza recibió familias de varios orígenes en 1856. Las divisiones lingüísticas y religiosas coexistieron con actividades agrícolas y artesanales. El asentamiento está documentado; las conexiones con Suiza en este atlas no atribuyen a todas las familias un mismo puerto de embarque.',['esperanza'])
g('german','Germanohablantes','#7c7f9f','La lengua no identifica un único Estado de origen.','Alemanes, austríacos y germanohablantes de otras soberanías no son una categoría estadística intercambiable. En Misiones hubo circuitos de colonización con etapas intermedias sudamericanas. La nacionalidad de un pasaporte debe leerse dentro de las fronteras de su momento.',['misiones','devoto'])
g('eastern','Europa centro-oriental','#937191','Imperios, nuevas fronteras y colonias.','La Galitzia de fines del siglo XIX pertenecía al Imperio austrohúngaro. Sus habitantes podían identificarse de maneras que no coinciden con la nacionalidad anotada al desembarcar. Apóstoles recibió un contingente polaco y ucraniano en 1897. El punto europeo es regional, no el domicilio de cada familia.',['galitzia','apostoles'])
g('jewish','Judíos europeos','#598f95','Una historia de colonización y de refugio.','Identidad judía y nacionalidad son variables distintas. La colonización rural, las instituciones urbanas y las fugas de la persecución pertenecen a momentos diferentes. Moisés Ville es un hito de 1889; el ingreso posterior de refugiados encontró restricciones. No se suman «judíos» e «italianos» como categorías excluyentes.',['jewish','jca','circular'])
g('welsh','Galeses','#5e8e77','Un viaje concreto hacia Patagonia.','El Mimosa salió de Liverpool el 28 de mayo de 1865 hacia Golfo Nuevo. Los documentos conservan nombres y billetes. La bibliografía ofrece recuentos de pasajeros ligeramente distintos; aquí no se adjudica una cifra única. Los primeros pobladores incluían trabajadores industriales, no solamente agricultores.',['mimosa','mimosaticket','mimosamuseum'])
g('exile','Exilio republicano','#aa6e79','Salir de España no garantizaba entrar a Argentina.','La derrota republicana produjo un exilio con escalas y destinos diversos. El Massilia representa un viaje estudiado de 1939. Las redes culturales y familiares ayudaron, pero los visados y las disposiciones administrativas podían impedir el desembarco. No toda la inmigración española fue exilio.',['massilia','exile'])
g('global','Otros destinos','#92958b','Argentina dentro de un sistema mundial.','Estados Unidos, Brasil, Canadá y Australia también recibieron migración europea. Las conexiones de contexto son ejemplos sin ponderación demográfica. Su función es mostrar alternativas, no presentar un inventario mundial exhaustivo ni itinerarios individuales.',['baily','santos','canada','australia'])
D.joinpath('groups.json').write_text(json.dumps(groups,ensure_ascii=False,indent=2))
routes=[]
def r(id,group,origin,dest,start,end,title,text,sources,layer='arrival',evidence='Corriente histórica',via=None):
 routes.append(dict(id=id,group=group,origin=origin,destination=dest,start=start,end=end,title=title,description=text,sources=sources,layer=layer,evidence=evidence,via=via or [],geometryNote='Conexión esquemática entre lugares documentados. Los puntos intermedios son una guía visual, no escalas verificadas. El grosor y la animación no representan volumen ni velocidad.',dateNote='Ventana histórica orientativa de la corriente; no afirma servicio continuo ni viajes en cada año.' if evidence!='Viaje documentado' else 'Fecha del viaje documentado. La línea no reproduce el derrotero náutico.'))
# Las guías oceánicas evitan insinuar cruces terrestres, pero no son itinerarios reconstruidos.
med=[[4,39],[-5.7,35.9],[-14,28],[-25,8],[-33,-7],[-40,-20],[-50,-30]]
north=[[-5,50],[-12,42],[-19,25],[-28,5],[-35,-10],[-43,-25],[-52,-33]]
atl=[[-12,38],[-19,22],[-28,5],[-35,-10],[-43,-25],[-52,-33]]
r('genoa-ba','italian','genoa','ba',1850,1960,'Génova → Buenos Aires','Génova fue uno de los grandes puertos de la emigración. La conexión representa la corriente italiana hacia el Río de la Plata, con intensidad variable y fuertes interrupciones bélicas. No es el recorrido de un barco concreto.',['journey','baily'],via=med)
r('naples-ba','italian','naples','ba',1880,1960,'Nápoles → Buenos Aires','La emigración desde el sur de Italia se integró a circuitos transatlánticos. El puerto indica una salida marítima, no la región natal de todos los pasajeros.',['journey','language'],via=[[12,38],*med])
r('trieste-ba','italian','trieste','ba',1880,1960,'Trieste → Buenos Aires','Trieste conectó territorios centroeuropeos con ultramar. Su soberanía cambió en el período. Esta ruta está agrupada con puertos de la península italiana por conveniencia de navegación, no como clasificación étnica de sus pasajeros.',['journey','devoto'],via=[[16,41],[18,37],[10,37],*med[1:]])
r('vigo-ba','spanish','vigo','ba',1880,1960,'Vigo → Buenos Aires','Conexión representativa entre puertos españoles y el Río de la Plata. Las redes familiares y las cartas de llamada orientaban decisiones y recursos. No contiene un recuento portuario ni una lista de buques.',['moya','journey','galicianwomen'],via=atl)
r('coruna-ba','spanish','coruna','ba',1880,1960,'A Coruña → Buenos Aires','El noroeste español participó de corrientes de ida y retorno. La línea relaciona el puerto con el destino; no adjudica a toda la migración gallega la misma salida.',['moya','galicianwomen'],via=atl)
r('barcelona-ba','spanish','barcelona','ba',1880,1960,'Barcelona → Buenos Aires','Un vínculo mediterráneo dentro de la emigración española. Los centros y asociaciones conservaron pertenencias regionales, mientras las trayectorias laborales se construían en Argentina.',['moya','journey'],via=med)
r('bordeaux-ba','french','bordeaux','ba',1850,1913,'Burdeos → Buenos Aires','La documentación general identifica Burdeos entre los puertos de salida. El sudoeste francés tuvo redes migratorias propias. Los destinos de los pasajeros no se reducían a la capital.',['journey','otero','subsidy'],via=atl)
r('havre-ba','french','havre','ba',1850,1929,'Le Havre → Buenos Aires','Los puertos franceses transportaron también personas de otros orígenes. Lugar de embarque, nacimiento y nacionalidad no son sinónimos.',['journey','otero'],via=north)
r('hamburg-ba','german','hamburg','ba',1880,1960,'Hamburgo → Buenos Aires','Hamburgo fue una puerta de salida hacia el Atlántico. La categoría germanohablante reúne experiencias diversas; no identifica la nacionalidad de todos sus pasajeros.',['journey','devoto'],via=[[7,54],[1,53],*north])
r('mimosa','welsh','liverpool','madryn',1865,1865,'Mimosa · Liverpool → Golfo Nuevo','El contrato de pasaje de Abraham Matthews y su familia consigna Liverpool–New Bay. El registro del buque y la colección galesa sitúan la salida el 28 de mayo de 1865. La llegada a Patagonia abrió una experiencia de asentamiento, no una tierra sin habitantes.',['mimosa','mimosaticket','mimosamuseum'],evidence='Viaje documentado',via=[[-6,52],[-12,40],[-22,20],[-32,0],[-40,-20],[-55,-38]])
r('massilia','exile','rochelle','ba',1939,1939,'Massilia · el viaje de 1939','El viaje del Massilia llevó refugiados y exiliados republicanos desde Francia a Buenos Aires. La investigación de Bárbara Ortuño reconstruye su travesía y los problemas de ingreso. La salida de Francia no vuelve franceses a los pasajeros.',['massilia','exile'],evidence='Viaje documentado',via=atl)
r('swiss-esperanza','swiss','swiss','esperanza',1856,1856,'Suiza → Esperanza','Conexión entre región de origen y colonia. La fundación de 1856 está documentada, pero esta línea omite el puerto, los transbordos y los medios de transporte que variaron entre familias.',['esperanza'],evidence='Origen y asentamiento',via=[[2,44],[-7,38],*atl[1:],[-58,-34]])
r('galitzia-apostoles','eastern','galitzia','apostoles',1897,1929,'Galitzia → Apóstoles','La llegada inicial de 1897 y la posterior colonización se documentan en la historia regional. La línea une una región histórica con un asentamiento; no reconstruye el camino ferroviario ni el puerto de cada familia.',['apostoles','galitzia'],evidence='Origen y asentamiento',via=[[14,46],[8,44],*med,[-58,-34]])
r('ba-rosario','italian','ba','rosario',1850,1960,'Buenos Aires → Rosario','Representa la distribución hacia un centro urbano y portuario de la región pampeana. Hubo circulación fluvial, ferroviaria y múltiples destinos intermedios. La conexión no identifica un modo de transporte exclusivo.',['integration','baily'],'interior','Conexión regional')
r('ba-mendoza','italian','ba','mendoza',1880,1960,'Buenos Aires → Mendoza','La expansión vitivinícola atrajo trabajadores, técnicos y empresarios europeos. Es una conexión territorial de síntesis, no una afirmación de que todos ingresaron por Buenos Aires.',['cuyo','wine'],'interior','Conexión regional')
r('ba-cordoba','spanish','ba','cordoba',1880,1960,'Buenos Aires → Córdoba','La inserción en ciudades del interior incluyó oficios, comercio y trabajo asalariado. Los estudios sobre movilidad advierten contra reducir la experiencia argentina a la capital.',['perez','integration'],'interior','Conexión regional')
r('ba-tandil','french','ba','tandil',1850,1913,'Buenos Aires → Tandil','Tandil es un caso de estudio de redes e integración de inmigrantes franceses. La línea es una relación entre lugares y no el viaje individual de todas las familias.',['otero'],'interior','Conexión regional')
r('ba-esperanza','swiss','ba','esperanza',1856,1913,'Hacia las colonias santafesinas','La colonización articuló proyectos públicos y privados. Buenos Aires funciona aquí como referencia de entrada; el trazado no identifica las escalas de cada contingente de Esperanza.',['esperanza','law'],'interior','Conexión regional')
r('ba-moises','jewish','ba','moises',1889,1929,'Buenos Aires → Moisés Ville','Moisés Ville recibió su primer grupo de familias en 1889. Las colonias judías ofrecieron un proyecto agrícola, instituciones y nuevas relaciones con el espacio rural argentino.',['jewish','jca'],'interior','Conexión regional')
r('ba-apostoles','eastern','ba','apostoles',1897,1929,'Buenos Aires → Apóstoles','La llegada a Misiones requirió una segunda etapa de desplazamiento. El mapa no reproduce todas las escalas fluviales o terrestres del contingente de 1897.',['apostoles','galitzia'],'interior','Conexión regional')
r('ba-eldorado','german','ba','eldorado',1919,1960,'Hacia las colonias de Misiones','Esquema de redistribución hacia un espacio de colonización. No agota los circuitos que pasaron por Brasil y otros territorios sudamericanos.',['misiones'],'interior','Conexión regional')
r('madryn-gaiman','welsh','madryn','gaiman',1865,1913,'Golfo Nuevo → valle del Chubut','El desembarco y el asentamiento agrícola fueron etapas diferentes. La relación entre los lugares ayuda a distinguir el punto de llegada marítima del espacio donde se organizó la colonia.',['mimosa','mimosamuseum'],'interior','Conexión regional')
r('ba-genoa-return','italian','ba','genoa',1880,1929,'El regreso a Italia','Las salidas formaron parte del sistema migratorio. Volver podía expresar un proyecto cumplido, dificultades o responsabilidades familiares. No se asigna a esta ruta el saldo nacional.',['journey','droller'],'return',via=list(reversed(med)))
r('ba-vigo-return','spanish','ba','vigo',1880,1960,'El regreso a España','El retorno podía ser temporal o definitivo. Las estadísticas agregadas de movimientos no identifican por sí solas las motivaciones ni el éxito económico de quien regresaba.',['moya','journey'],'return',via=list(reversed(atl)))
r('genoa-ny','global','genoa','ny',1870,1914,'Otra América · Nueva York','La comparación de Baily estudia italianos en Buenos Aires y Nueva York. La ruta muestra una alternativa dentro del sistema atlántico; no implica que quienes viajaron a Nueva York pasaran por Argentina.',['baily'],'context',via=[[4,39],[-6,36],[-20,36],[-45,39],[-65,40]])
r('genoa-santos','global','genoa','santos',1888,1960,'Otra América · Santos','El acervo del Museu da Imigração conserva listas de buques con desembarque previsto en Santos. Génova funciona como puerto europeo representativo; no es la procedencia exclusiva del conjunto documental.',['santos'],'context',via=med[:-1])
r('liverpool-halifax','global','liverpool','halifax',1946,1960,'Posguerra · Halifax','Pier 21 fue un lugar de recepción de migrantes y desplazados europeos. Liverpool es un punto de referencia británico en este esquema comparativo, no el puerto de todos los pasajeros.',['canada'],'context',via=[[-10,52],[-30,49],[-48,47]])
r('london-sydney','global','london','sydney',1946,1960,'Posguerra · Australia','El museo marítimo australiano documenta acuerdos y pasajes asistidos de posguerra. Esta conexión mundial muestra origen y destino generales; la guía por el océano no representa una ruta de un buque ni una elección entre Suez y el Cabo.',['australia'],'context',via=[[-5,50],[-15,30],[-20,0],[10,-35],[45,-40],[90,-42],[130,-40]])
